-- ===========================================================================
-- Jata Cafe - seed data
--
-- GENERATED from the original SQLite database so the menu, prices and copy
-- are byte-identical to what the cafe already had. Do not hand-edit; edit the
-- menu through the /ms dashboard once the app is running.
--
-- Apply ONCE after 0001_init.sql:
--     npm run db:seed
-- or paste into the Supabase SQL editor.
--
-- Re-runnable: every insert is ON CONFLICT DO NOTHING, so running it twice
-- does not duplicate the menu. Identity columns are inserted explicitly with
-- OVERRIDING SYSTEM VALUE to preserve the original ids - promotions.target_id
-- points at a category id, so those ids must survive. Sequences are advanced
-- to match at the end.
--
-- Does NOT seed: admin_users (created by scripts/seed.mjs from SEED_ADMIN_*),
-- orders, customers, events, sessions, login_attempts.
-- ===========================================================================

begin;


-- settings: 19 rows

-- categories: 6 rows

-- menu_items: 48 rows

-- banners: 3 rows

-- delivery_zones: 8 rows

-- promotions: 3 rows

-- Advance identity sequences past the explicitly-inserted ids, otherwise the
-- next dashboard insert would collide with an existing primary key.
select setval(pg_get_serial_sequence('categories', 'id'), coalesce((select max(id) from categories), 1));
select setval(pg_get_serial_sequence('menu_items', 'id'), coalesce((select max(id) from menu_items), 1));
select setval(pg_get_serial_sequence('banners', 'id'), coalesce((select max(id) from banners), 1));
select setval(pg_get_serial_sequence('delivery_zones', 'id'), coalesce((select max(id) from delivery_zones), 1));
select setval(pg_get_serial_sequence('promotions', 'id'), coalesce((select max(id) from promotions), 1));

commit;
